In nfc_llcp_recv_hdlc() and nfc_llcp_recv_disc(), when the socket
state is LLCP_CLOSED, the code correctly calls release_sock() and
nfc_llcp_sock_put() but fails to return. Execution falls through to
the remainder of the function, which calls release_sock() and
nfc_llcp_sock_put() again. This results in a double release_sock()
and a refcount underflow via double nfc_llcp_sock_put(), leading to
a use-after-free.

Add the missing return statements after the LLCP_CLOSED branches
in both functions to prevent the fall-through.

Fixes: d646960f7986 ("NFC: Initial LLCP support")
Signed-off-by: Junxi Qian <qjx1298677004@gmail.com>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Link: https://patch.msgid.link/20260408081006.3723-1-qjx1298677004@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In nfc_llcp_recv_hdlc() and nfc_llcp_recv_disc(), when the socket state is LLCP_CLOSED, the code correctly calls release_sock() and nfc_llcp_sock_put() but lacks a return statement, causing execution to fall through to the remainder of the function. This results in double release_sock() and double nfc_llcp_sock_put(), leading to a refcount underflow and use-after-free.

Here is the patch:

 static void nfc_llcp_recv_hdlc(struct nfc_llcp_local *local,
 			       struct sk_buff *skb)
 {
 	struct nfc_llcp_sock *llcp_sock;
 	struct sock *sk;
 	u8 dsap, ssap, ptype, ns, nr;

 	ptype = nfc_llcp_ptype(skb);
 	dsap = nfc_llcp_dsap(skb);
 	ssap = nfc_llcp_ssap(skb);
 	ns = nfc_llcp_ns(skb);
 	nr = nfc_llcp_nr(skb);

 	pr_debug("%d %d R %d S %d\n", dsap, ssap, nr, ns);

 	llcp_sock = nfc_llcp_sock_get(local, dsap, ssap);
 	if (llcp_sock == NULL) {
 		nfc_llcp_send_dm(local, dsap, ssap, LLCP_DM_NOCONN);
 		return;
 	}

 	sk = &llcp_sock->sk;
 	lock_sock(sk);
 	if (sk->sk_state == LLCP_CLOSED) {
 		release_sock(sk);
 		nfc_llcp_sock_put(llcp_sock);
+		return;
 	}

 	/* Pass the payload upstream */
 	if (ptype == LLCP_PDU_I) {
 		pr_debug("I frame, queueing on %p\n", &llcp_sock->sk);

 		if (ns == llcp_sock->recv_n)
 			llcp_sock->recv_n = (llcp_sock->recv_n + 1) % 16;
 		else
 			pr_err("Received out of sequence I PDU\n");

 		skb_pull(skb, LLCP_HEADER_SIZE + LLCP_SEQUENCE_SIZE);
 		if (!sock_queue_rcv_skb(&llcp_sock->sk, skb)) {
 			/*
 			 * I frames will be freed from the socket layer, so we
 			 * need to keep them alive until someone receives them.
 			 */
 			skb_get(skb);
 		} else {
 			pr_err("Receive queue is full\n");
 		}
 	}

 	/* Remove skbs from the pending queue */
 	if (llcp_sock->send_ack_n != nr) {
 		struct sk_buff *s, *tmp;
 		u8 n;

 		llcp_sock->send_ack_n = nr;

 		/* Remove and free all skbs until ns == nr */
 		skb_queue_walk_safe(&llcp_sock->tx_pending_queue, s, tmp) {
 			n = nfc_llcp_ns(s);

 			skb_unlink(s, &llcp_sock->tx_pending_queue);
 			kfree_skb(s);

 			if (n == nr)
 				break;
 		}

 		/* Re-queue the remaining skbs for transmission */
 		skb_queue_reverse_walk_safe(&llcp_sock->tx_pending_queue,
 					    s, tmp) {
 			skb_unlink(s, &llcp_sock->tx_pending_queue);
 			skb_queue_head(&local->tx_queue, s);
 		}
 	}

 	if (ptype == LLCP_PDU_RR)
 		llcp_sock->remote_ready = true;
 	else if (ptype == LLCP_PDU_RNR)
 		llcp_sock->remote_ready = false;

 	if (nfc_llcp_queue_i_frames(llcp_sock) == 0 && ptype == LLCP_PDU_I)
 		nfc_llcp_send_rr(llcp_sock);

 	release_sock(sk);
 	nfc_llcp_sock_put(llcp_sock);
 }

 static void nfc_llcp_recv_disc(struct nfc_llcp_local *local,
 			       const struct sk_buff *skb)
 {
 	struct nfc_llcp_sock *llcp_sock;
 	struct sock *sk;
 	u8 dsap, ssap;

 	dsap = nfc_llcp_dsap(skb);
 	ssap = nfc_llcp_ssap(skb);

 	if ((dsap == 0) && (ssap == 0)) {
 		pr_debug("Connection termination");
 		nfc_dep_link_down(local->dev);
 		return;
 	}

 	llcp_sock = nfc_llcp_sock_get(local, dsap, ssap);
 	if (llcp_sock == NULL) {
 		nfc_llcp_send_dm(local, dsap, ssap, LLCP_DM_NOCONN);
 		return;
 	}

 	sk = &llcp_sock->sk;
 	lock_sock(sk);

 	nfc_llcp_socket_purge(llcp_sock);

 	if (sk->sk_state == LLCP_CLOSED) {
 		release_sock(sk);
 		nfc_llcp_sock_put(llcp_sock);
+		return;
 	}

 	if (sk->sk_state == LLCP_CONNECTED) {
 		nfc_put_device(local->dev);
 		sk->sk_state = LLCP_CLOSED;
 		sk->sk_state_change(sk);
 	}

 	nfc_llcp_send_dm(local, dsap, ssap, LLCP_DM_DISC);

 	release_sock(sk);
 	nfc_llcp_sock_put(llcp_sock);
 }



